import groovy.json.JsonOutput
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.nio.charset.StandardCharsets

def proyecto = testRunner.testCase.testSuite.project
def clave = proyecto.getPropertyValue('ClaveTecnica')
assert clave && clave.getBytes(StandardCharsets.UTF_8).length >= 32 : 'Configura ClaveTecnica en las propiedades del proyecto.'
def ahora = System.currentTimeMillis().intdiv(1000)
def b64 = { byte[] bytes -> Base64.urlEncoder.withoutPadding().encodeToString(bytes) }
def header = b64(JsonOutput.toJson([alg:'HS256', typ:'JWT']).getBytes(StandardCharsets.UTF_8))
def payload = b64(JsonOutput.toJson([
    iss:'fastfood-internal', sub:'order-service', aud:['comprobante-soap-service'],
    scope:'COMPROBANTE_OPERAR', jti:UUID.randomUUID().toString(), iat:ahora, exp:ahora + 60
]).getBytes(StandardCharsets.UTF_8))
def contenido = header + '.' + payload
def mac = Mac.getInstance('HmacSHA256')
mac.init(new SecretKeySpec(clave.getBytes(StandardCharsets.UTF_8), 'HmacSHA256'))
context.setProperty('TokenSoap', contenido + '.' + b64(mac.doFinal(contenido.getBytes(StandardCharsets.UTF_8))))
log.info('Credencial tecnica renovada para esta solicitud (60 segundos).')
log.info('Bearer ' + context.getProperty('TokenSoap'))

def proyecto = testRunner.testCase.testSuite.project
if (!proyecto.getPropertyValue('PedidoPrueba')?.trim()) {
    proyecto.setPropertyValue('PedidoPrueba', (9900000000000L + new Random().nextInt(1000000000)).toString())
}
assert proyecto.getPropertyValue('PedidoPrueba') ==~ /[1-9][0-9]*/ : 'PedidoPrueba debe ser un numero positivo.'
log.info('Venta SOAP de demostracion: pedido ' + proyecto.getPropertyValue('PedidoPrueba'))

