import groovy.util.XmlSlurper
def leer = { nombre -> new XmlSlurper().parseText(testRunner.testCase.getTestStepByName(nombre).testRequest.responseContent) }
def nodo = { xml, nombre -> xml.depthFirst().find { it.name() == nombre } }
def primero = leer('Generar')
def repetido = leer('Repetir emision')
def consultado = leer('Consultar generado')
assert nodo(repetido, 'creado').text() == 'false' : 'El reintento no debe crear otro documento.'
def id = nodo(primero, 'id').text()
assert id && id == nodo(repetido, 'id').text() && id == nodo(consultado, 'id').text()
assert nodo(primero, 'numero').text() == nodo(consultado, 'numero').text()
log.info('Emision, reintento y consulta recuperaron el mismo comprobante.')
